def once(text,old,new):
    if text.count(old)!=1: raise ValueError('CONE redraw anchor drift: '+repr(old[:80]))
    return text.replace(old,new,1)

def transform(text,restore=False):
    if '#include "htcleogsredrawtrace.inl"' in text:
        for old,new in reversed(EDITS): text=once(text,new,old)
    elif 'HtcleoGsRedraw' in text: raise ValueError('Partial GS redraw observation')
    if hashlib.sha256(text.encode('latin-1')).hexdigest()!=BASE_SHA:
        raise ValueError('CONE differs from exact821 source')
    if not restore:
        for old,new in EDITS: text=once(text,old,new)
    return text

def main():
    p=argparse.ArgumentParser();p.add_argument('root',type=Path);p.add_argument('--restore',action='store_true');a=p.parse_args()
    path=a.root/REL/NAME;old=path.read_text(encoding='latin-1');new=transform(old,a.restore)
    if transform(new,True)!=transform(old,True): raise ValueError('CONE inverse failed')
    if not a.restore and transform(new)!=new: raise ValueError('CONE idempotence failed')
    if old!=new: path.write_text(new,encoding='latin-1')
    if not a.restore:
        helper=HERE.parent/'hd2/qsd8250-native-bsp/diagnostics/htcleogsredrawtrace.inl'
        (path.parent/helper.name).write_bytes(helper.read_bytes())
    print('HTCLEO_GSAPP_REDRAW='+('restored' if a.restore else 'GS-first-native-redraw32-and-pre-native-panic-no-queue-or-drawing-change'))

if __name__=='__main__': main()
